export const meta = {
  name: 'r12-coder-dispatch',
  description: 'Dispatch the five frozen R12 coder tasks in parallel, semantically evaluate each against its CHECKLIST task block, and run same-seat corrections',
  whenToUse: 'Operator-signed dispatch of the frozen R12 tasklist in CHECKLIST.md',
  phases: [
    { title: 'Code', detail: 'five parallel coders, one per R12 task, in-place edits on disjoint scopes' },
    { title: 'Evaluate', detail: 'independent semantic evaluators: requirements lens + preservation lens per task' },
    { title: 'Correct', detail: 'same-seat correction rounds (max 2) with re-evaluation' },
  ],
}

const ROOT = '/home/robin/Desktop/DevProjects/natally-ai-studio'
const TASKS = [
  { id: 'R12-A', scope: 'src/marketing.tsx src/marketing.css' },
  { id: 'R12-B', scope: 'src/components/Astrolabe3D.tsx' },
  { id: 'R12-C', scope: 'src/App.tsx src/components/NatallyChatbot.tsx src/components/ReadingStage.tsx' },
  { id: 'R12-D', scope: 'src/services/authoredChartExplanations.ts src/services/authoredEducationSession.ts' },
  { id: 'R12-E', scope: 'src/main.tsx scripts/build-web.mjs scripts/stage-marketing-overlay.mjs scripts/pwa-build.mjs .env.example .env' },
]

const CODER_SCHEMA = { type: 'object', required: ['taskId', 'status', 'summary', 'mapping'], properties: {
  taskId: { type: 'string' },
  status: { type: 'string', enum: ['completed', 'blocked'] },
  summary: { type: 'string' },
  mapping: { type: 'array', items: { type: 'object', required: ['requirement', 'location'], properties: { requirement: { type: 'string' }, location: { type: 'string' } } } },
  resolvedAnchors: { type: 'array', items: { type: 'string' } },
  blockers: { type: 'array', items: { type: 'string' } },
} }

const EVAL_SCHEMA = { type: 'object', required: ['taskId', 'lens', 'pass', 'requirementVerdicts'], properties: {
  taskId: { type: 'string' },
  lens: { type: 'string' },
  pass: { type: 'boolean' },
  requirementVerdicts: { type: 'array', items: { type: 'object', required: ['requirement', 'met'], properties: { requirement: { type: 'string' }, met: { type: 'boolean' }, note: { type: 'string' } } } },
  deviations: { type: 'array', items: { type: 'object', required: ['problem'], properties: { requirement: { type: 'string' }, problem: { type: 'string' } } } },
} }

const coderPrompt = (t) => `You are coder seat ${t.id} in the Natally repository at ${ROOT} (React/TypeScript + Vite; working tree on master).

FIRST: Read ${ROOT}/CHECKLIST.md and locate exactly THREE parts, ignoring everything else in that file: the section "## Coder instructions — read before your task, then work ONLY your task", the section "## Environment keys — frozen verbatim", and YOUR task block "## Task ${t.id}" (from that heading until the next "---" separator). Do NOT read other task blocks, other repo documents, or any files outside your scope.

Then execute your task exactly:
- You may READ and EDIT only these scope files: ${t.scope}
- For any symbol or anchor context you need beyond your task text and scope files, use the CodeGraph CLI: run \`codegraph query "<symbol or question>"\` (the .codegraph index is initialized). Do not browse other source files.
- Edit files in place in the working tree. Do NOT run any mutating git command (no add/commit/checkout/restore), no builds, no typecheck, no lint, no tests, no package installs.
- Real content only — no placeholders, no mocks, no fabricated behavior (project rule, absolute).
- If a requirement is genuinely impossible as written, stop and report it as a blocker citing the exact blocking text; do not improvise a substitute design.

Finish by producing your structured report: status completed or blocked; a summary in your own words of what the code now does; a mapping row for EVERY numbered requirement of your task to the file:line where it is realized; RESOLVED anchor lines; and any blockers.`

const evalReqPrompt = (t) => `You are an independent semantic evaluator (requirements lens) for task ${t.id} in the Natally repository at ${ROOT}.

Read ${ROOT}/CHECKLIST.md section "## Task ${t.id}" (from that heading to the next "---"). It defines numbered requirements (${t.id}1, ${t.id}2, ...), a closed scope list, frozen contracts and preserve/forbid clauses.

Then READ the actual implementation in the scope files: ${t.scope} (use \`codegraph query "<symbol>"\` for symbol context; for .env, which may be gitignored, read the file directly). Judge by READING the code and reasoning about what it actually does. You must NOT base any verdict on grepping for strings or markers: a present string is not a met requirement. Trace the real control flow and data flow.

For EVERY numbered requirement decide: fully realized exactly as written, nothing missing? Also flag anything implemented that no requirement asks for, and any violation of the task's Forbidden/Preserve clauses. Return a requirementVerdicts row for each numbered requirement, deviations for each problem found, and pass=true ONLY if every requirement is fully met with nothing extra.`

const evalPreservePrompt = (t) => `You are an independent semantic evaluator (preservation lens) for task ${t.id} in the Natally repository at ${ROOT}.

Run in ${ROOT}: \`git diff -- ${t.scope}\` and \`git diff --name-only\`. (If a scope file is gitignored, read that file directly and reason about what the task permitted to change in it.)

Read every diff hunk semantically (not by grep) and compare against the task block "## Task ${t.id}" in ${ROOT}/CHECKLIST.md: every hunk must serve a numbered requirement of that task. Flag: (a) any change to files outside the scope list; (b) hunks inside scope files that no requirement names; (c) any alteration of behavior the task explicitly preserves or forbids touching; (d) new dependencies, placeholder content, or customer-facing fakery. Return deviations for each problem, a requirementVerdicts row per preserved-area you checked (requirement name = the preserved clause, met = intact), and pass=true ONLY when every change is requirement-named and preservation is intact.`

const correctPrompt = (t, devs, round) => `You are the SAME coder seat ${t.id}, correction round ${round}, in the Natally repository at ${ROOT}. Independent semantic evaluation of your previous edit found these deviations:

${devs.map((d, i) => `${i + 1}. ${d.requirement ? '[' + d.requirement + '] ' : ''}${d.problem}`).join('\n')}

Re-read your task block "## Task ${t.id}" and the "## Coder instructions" section in ${ROOT}/CHECKLIST.md. Fix ONLY these deviations in your scope files (${t.scope}); change nothing else that already passed. Same rules as before: in-place edits only, no git/build/typecheck/test runs, real content only, \`codegraph query\` for symbol context. Return the same structured report, updated.`

phase('Code')
log('Dispatching 5 parallel coder seats R12-A..R12-E on disjoint scopes')

const outcomes = await pipeline(TASKS,
  (t) => agent(coderPrompt(t), { label: `code:${t.id}`, phase: 'Code', schema: CODER_SCHEMA }),
  async (code, t) => {
    if (!code || code.status === 'blocked') return { id: t.id, code, blocked: true, rounds: [] }
    const verdicts = (await parallel([
      () => agent(evalReqPrompt(t), { label: `eval-req:${t.id}`, phase: 'Evaluate', schema: EVAL_SCHEMA }),
      () => agent(evalPreservePrompt(t), { label: `eval-preserve:${t.id}`, phase: 'Evaluate', schema: EVAL_SCHEMA }),
    ])).filter(Boolean)
    return { id: t.id, code, blocked: false, rounds: [{ corrections: null, verdicts }] }
  },
  async (state, t) => {
    if (!state || state.blocked) return state
    const devs = () => (state.rounds[state.rounds.length - 1].verdicts || []).flatMap(v => (v.deviations || []).map(d => ({ requirement: d.requirement || '', problem: d.problem })))
    for (let round = 1; round <= 2 && devs().length > 0; round++) {
      log(`${t.id}: correction round ${round} — ${devs().length} deviation(s)`)
      const fix = await agent(correctPrompt(t, devs(), round), { label: `correct:${t.id}#${round}`, phase: 'Correct', schema: CODER_SCHEMA })
      if (!fix) break
      const verdicts = (await parallel([
        () => agent(evalReqPrompt(t), { label: `re-eval-req:${t.id}#${round}`, phase: 'Correct', schema: EVAL_SCHEMA }),
        () => agent(evalPreservePrompt(t), { label: `re-eval-preserve:${t.id}#${round}`, phase: 'Correct', schema: EVAL_SCHEMA }),
      ])).filter(Boolean)
      state.rounds.push({ corrections: fix, verdicts })
    }
    state.final = state.rounds[state.rounds.length - 1].verdicts || []
    state.pass = state.final.length > 0 && state.final.every(v => v.pass)
    return state
  }
)

const summary = outcomes.filter(Boolean).map(o => ({
  id: o.id,
  blocked: !!o.blocked,
  pass: o.pass === true,
  rounds: o.rounds.length,
  summary: (o.code && o.code.summary) || '',
  mapping: (o.code && o.code.mapping) || [],
  blockers: (o.code && o.code.blockers) || [],
  remainingDeviations: (o.final || []).flatMap(v => (v.deviations || []).map(d => (d.requirement ? '[' + d.requirement + '] ' : '') + d.problem)),
}))
log('Dispatch complete: ' + summary.map(s => `${s.id}=${s.blocked ? 'BLOCKED' : (s.pass ? 'PASS' : 'DEVIATIONS-REMAIN')}`).join(', '))
return summary
